system {
 host-name SEED-HOST;
 login { user SEED-USER { full-name "SEED-PERSON"; authentication { encrypted-password "SEED-HASH"; ssh-rsa "ssh-rsa SEED-SSH"; } } }
 radius-server 192.0.2.20 { secret "SEED-RADIUS"; }
}
snmp { community "SEED-COMMUNITY" { authorization read-only; } }
security { ike { policy SEED-POLICY { pre-shared-key { ascii-text "SEED-PSK"; } } } }
interfaces { ge-0/0/0 { unit 0 { family inet { address 192.0.2.10/24; } } } }
